local R=dofile('tests/kernel_objects_harness.lua')
local n=0
local function case(name,fn)R.clientCase(name,fn);n=n+1 end
local function payload()return R.seed()end
local function count(r)local n=0;for _ in pairs(r.entities)do n=n+1 end;return n end
case('initial empty',function(r)assert(r.tick()==1200 and count(r)==0)end)
case('near spawn actual PR module',function(r)r.value=payload();assert(r.tick()==1200);assert(count(r)==1 and r.objects.get(1).handle==101)end)
case('far object no spawn',function(r)local p=payload();p.objects[1].coords.x=999;r.value=p;r.tick();assert(count(r)==0)end)
case('distance despawn and respawn',function(r)r.value=payload();r.tick();r.positions[11]=R.vector(999,0,0);r.tick();assert(count(r)==0)
    r.positions[11]=R.vector();r.tick();assert(count(r)==1 and r.objects.get(1).handle==102)end)
case('disabled despawns',function(r)r.value=payload();r.tick();local p=payload();p.enabled=false;r.apply(p);r.tick();assert(count(r)==0)end)
case('payload nil clears',function(r)r.value=payload();r.tick();r.apply(nil);assert(count(r)==0 and not r.objects.get(1))end)
case('bad objects ignored',function(r)r.apply({objects=false});assert(next(r.objects.entries)==nil)end)
case('missing numeric ID ignored',function(r)r.apply({objects={{model='X'},{id='not-id'}}});assert(next(r.objects.entries)==nil)end)
case('scene listing sort',function(r)local p=payload();p.objects[2]={id=5,sceneId=1,model='X'};p.objects[3]={id=2,sceneId=1,model='Y'}
    r.apply(p);local a=r.objects.getByScene('1');assert(a[1].id==1 and a[2].id==2 and a[3].id==5)end)
case('update transform reuses handle',function(r)r.value=payload();r.tick();local p=payload();p.objects[1].coords.x=8;r.apply(p);assert(r.objects.get(1).handle==101 and r.positions[101].x==8)end)
case('model replacement same handle retained',function(r)r.value=payload();r.tick();local p=payload();p.objects[1].model='changed';r.apply(p);r.tick();assert(r.nextEntity==101 and r.objects.get(1).model=='changed')end)
case('debug toggles and zero frame',function(r)r.value=payload();r.tick();assert(r.objects.toggleDebug());assert(r.tick(2)==0);assert(not r.objects.toggleDebug());assert(r.tick(2)==500)end)
case('outline missing returns false',function(r)assert(not r.objects.setOutline(1,true))end)
case('outline and teleport',function(r)r.value=payload();r.tick();assert(r.objects.setOutline('1',true,1,2,3));assert(r.objects.teleportTo(1));assert(r.positions[11].x==1)end)
case('teleport missing',function(r)assert(not r.objects.teleportTo(999))end)
case('unrelated stop ignored',function(r)r.value=payload();r.tick();local n=#r.trace;r.stop('pr_bridge');assert(#r.trace==n and count(r)==1)end)
case('own stop clears known handles',function(r)r.value=payload();r.tick();r.stop();assert(count(r)==0 and r.objects.get(1).handle==nil and not r.objects.editorActive)end)
case('invalid PR model',function(r)r.validModel=false;r.value=payload();r.tick();assert(count(r)==0)end)
case('create native zero',function(r)r.createZero=true;r.value=payload();r.tick();assert(count(r)==0)end)
case('native create exception swallowed by PR',function(r)r.createError=true;r.value=payload();r.tick();assert(count(r)==0)end)
case('streaming absent',function(r)r.library.fivem.streaming=nil;local ok,e=r.objects.createPreview('X',1);assert(not ok and e=='streaming_unavailable')end)
case('create preview confirm serializes and deletes',function(r)assert(r.objects.createPreview('X',1,function(id)assert(id==99);r.record('created',id)end));assert(r.objects.editorActive and r.targetDisabled)
    r.rpcHook=function(_,obj)assert(obj.coords.x==8.123 and obj.coords.y==9.235 and obj.rotation.z==3);return true,99 end
    r.finish(true);assert(count(r)==0 and not r.targetDisabled and not r.objects.editorActive)end)
case('create preview cancelled',function(r)r.objects.createPreview('X',1);r.finish(false);assert(count(r)==0 and not r.targetDisabled)end)
case('create server denied deletes preview',function(r)r.objects.createPreview('X',1);r.rpcHook=function()return false,'no_permission'end;r.finish(true);assert(count(r)==0)end)
case('gizmo unavailable leaked preview legacy',function(r)r.library.fivem.gizmo=nil;assert(r.objects.createPreview('X',1));assert(count(r)==1 and not r.objects.editorActive)end)
case('gizmo start fails cleans preview',function(r)r.gizmoFailed=true;assert(r.objects.createPreview('X',1));assert(count(r)==0 and not r.targetDisabled)end)
case('busy second preview retained',function(r)r.objects.createPreview('X',1);assert(r.objects.createPreview('Y',1));assert(count(r)==2);r.finish(false);assert(count(r)==1)end)
case('edit missing',function(r)local ok,e=r.objects.edit(999);assert(not ok and e=='object_not_found')end)
case('edit spawn failure',function(r)r.apply(payload());r.validModel=false;local ok,e=r.objects.edit(1);assert(not ok and e=='spawn_failed')end)
case('edit confirmation callback',function(r)r.value=payload();r.tick();assert(r.objects.edit(1,function()r.record('updated')end));r.finish(true);assert(r.collisions[101]and not r.targetDisabled)end)
case('edit cancellation leaves collision disabled',function(r)r.value=payload();r.tick();r.objects.edit(1);r.finish(false);assert(r.collisions[101]==false and not r.objects.editorActive)end)
case('edit rejected restores transform',function(r)r.value=payload();r.tick();r.objects.edit(1);r.positions[101]=R.vector(9,9,9)
    r.rpcHook=function()return false,'save_failed'end;r.finish(true);assert(r.positions[101].x==1 and r.rotations[101].z==40)end)
case('edit gizmo failure retains method true',function(r)r.value=payload();r.tick();r.gizmoFailed=true;assert(r.objects.edit(1));assert(r.collisions[101]==false)end)
case('RPC exception skips preview delete',function(r)r.objects.createPreview('X',1);r.rpcHook=function()error('fixture-rpc',0)end
    assert(not pcall(r.finish,true));assert(count(r)==1 and not r.objects.editorActive)end)
case('late finish after resource stop',function(r)r.objects.createPreview('X',1);r.stop();r.finish(true);assert(count(r)==0)end)
case('late streaming after payload removal',function(r)r.value=payload();r.loaded=false;local co=r.run(r.initial[1]);r.apply(nil);r.loaded=true;r.resume(co)
    assert(count(r)==1 and next(r.objects.entries)==nil)end)
case('streaming timeout releases model in PR',function(r)r.value=payload();r.loaded=false;local co=r.run(r.initial[1]);for _=1,6 do r.resume(co)end;assert(count(r)==0)end)
case('debug text native fallback',function(r)r.value=payload();r.tick();r.library.fivem.blips=nil;r.objects.toggleDebug();r.tick(2)end)
print('PASS objects renderer/editor differentials '..n)
